import boto3


def translate_dictionary_values(payload, config=None):
    config = config or {}
    client = boto3.client("translate", region_name=config.get("region"))
    translated_dictionary = {}
    for key, value in payload["dictionary"].items():
        response = client.translate_text(
            Text=value,
            SourceLanguageCode=payload["source_language"],
            TargetLanguageCode=payload["target_language"],
        )
        translated_dictionary[key] = response["TranslatedText"]
    return {
        "dictionary": translated_dictionary,
        "source_language": payload["source_language"],
        "target_language": payload["target_language"],
    }

import boto3

def get_translate_client(region_name=None):
    return boto3.client("translate", region_name=region_name)

def get_comprehend_client(region_name=None):
    return boto3.client("comprehend", region_name=region_name)

def get_polly_client(region_name=None):
    return boto3.client("polly", region_name=region_name)

def get_sagemaker_runtime_client(region_name=None):
    return boto3.client("sagemaker-runtime", region_name=region_name)

from typing import List, Dict, Any

def create_text_translation_payload(text: str, source_language: str, target_language: str) -> Dict[str, str]:
    return {
        "text": text,
        "source_language": source_language,
        "target_language": target_language,
    }

def create_batch_translation_payload(texts: List[str], source_language: str, target_language: str) -> Dict[str, Any]:
    return {
        "texts": texts,
        "source_language": source_language,
        "target_language": target_language,
    }

def create_markup_translation_payload(markup: str, source_language: str, target_language: str) -> Dict[str, str]:
    return {
        "markup": markup,
        "source_language": source_language,
        "target_language": target_language,
    }

def create_dictionary_translation_payload(dictionary: Dict[str, str], source_language: str, target_language: str) -> Dict[str, Any]:
    return {
        "dictionary": dictionary,
        "source_language": source_language,
        "target_language": target_language,
    }

def create_comprehend_text_payload(text: str, language_code: str) -> Dict[str, str]:
    return {
        "text": text,
        "language_code": language_code
    }

def create_polly_synthesis_payload(text: str, voice_id: str, output_format: str = "mp3") -> Dict[str, str]:
    return {
        "text": text,
        "voice_id": voice_id,
        "output_format": output_format
    }

